import{_ as a,o as e,c as o,a2 as n}from"./chunks/framework.a6FUKr6c.js";const y=JSON.parse('{"title":"@chamvi/tool-mail","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tool-mail.md","filePath":"reference/tool-mail.md","lastUpdated":1794560227000}'),t={name:"reference/tool-mail.md"};function l(c,s,p,r,d,i){return e(),o("div",null,[...s[0]||(s[0]=[n(`<h1 id="chamvi-tool-mail" tabindex="-1">@chamvi/tool-mail <a class="header-anchor" href="#chamvi-tool-mail" aria-label="Permalink to &quot;@chamvi/tool-mail&quot;">​</a></h1><p>Read-only mail tools for chamvi agents: search, read and thread mails and extract attachment text over IMAP (Gmail, dovecot, Cyrus, ...), without ever changing a mailbox. The public API of <code>packages/tool-mail/src/index.ts</code> and its <code>/module</code> entry. See <a href="/guide/tools#mail-and-calendar-tools">Mail and calendar tools</a> for an example.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#DCE9F2;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/tool-mail</span><span style="color:#E7C58C;"> @chamvi/core</span><span style="color:#E7C58C;"> ai</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><p><code>@chamvi/core</code> and <code>ai</code> are peer dependencies; <code>@chamvi/app</code> is an optional peer of <code>@chamvi/tool-mail/module</code>.</p><h2 id="mailtools" tabindex="-1">mailTools <a class="header-anchor" href="#mailtools" aria-label="Permalink to &quot;mailTools&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> mailTools(options?: MailToolsOptions): ToolSet; </span><span style="color:#7F95A6;">// { mail_accounts, mail_search, mail_get, mail_attachment, mail_thread }</span></span>
<span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> createMailClient(accounts: MailAccount[], options?: MailClientOptions): IMailClient;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_REQUEST_ERROR_CODE: </span><span style="color:#E7C58C;">&#39;mail_request&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_TIMEOUT_MS: </span><span style="color:#E7C58C;">30_000</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_SEARCH_DEFAULT_LIMIT: </span><span style="color:#E7C58C;">20</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_SEARCH_MAX_LIMIT: </span><span style="color:#E7C58C;">50</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_THREAD_MAX_REFERENCES: </span><span style="color:#E7C58C;">10</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_BODY_MAX_CHARS: </span><span style="color:#E7C58C;">50_000</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_ATTACHMENT_MAX_CHARS: </span><span style="color:#E7C58C;">20_000</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_HTML_MAX_CHARS: </span><span style="color:#E7C58C;">1_000_000</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_PDF_MAX_PAGES: </span><span style="color:#E7C58C;">50</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_ZIP_PART_MAX_BYTES: </span><span style="color:#E7C58C;">10_485_760</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_ZIP_TOTAL_MAX_BYTES: </span><span style="color:#E7C58C;">20_971_520</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_OOXML_MAX_SLIDES: </span><span style="color:#E7C58C;">200</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_SUBJECT_MAX_CHARS: </span><span style="color:#E7C58C;">1000</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_ADDRESSES_MAX_CHARS: </span><span style="color:#E7C58C;">2000</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_INVITE_FIELD_MAX_CHARS: </span><span style="color:#E7C58C;">500</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_INVITES_MAX: </span><span style="color:#E7C58C;">10</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_FETCH_MAX_BYTES: </span><span style="color:#E7C58C;">26_214_400</span><span style="color:#DCE9F2;">;</span></span></code></pre></div><p>The tools use <code>client</code>, else a client of <code>accounts</code>, else the client the module <a href="#toolmailmodule">provided on the engine</a> (without one, each call fails with <code>context_not_provided</code>). Throws <code>InvalidAgentDefinitionError</code> for options that are no object, a <code>client</code> that is no mail client, an account without <code>id</code> (<code>^[a-z0-9]+(-[a-z0-9]+)*$</code>), <code>host</code>, <code>user</code> or <code>password</code>, a bad <code>security</code>, <code>port</code>, <code>address</code>, <code>folders</code> or <code>gmail</code>, a duplicate id, a <code>timeoutMs</code> that is no integer from 1 to 2^31 - 1 and a clock without <code>now()</code> and <code>setTimeout()</code>. No message echoes a value.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Input</th><th>Result</th></tr></thead><tbody><tr><td><code>mail_accounts</code></td><td>none</td><td><code>MailAccountView[]</code>: each account with its folders (path, special use)</td></tr><tr><td><code>mail_search</code></td><td><code>account</code>, <code>query?</code>, <code>folder?</code>, <code>from?</code>, <code>to?</code>, <code>subject?</code>, <code>since?</code>, <code>before?</code> (ISO dates), <code>unread?</code>, <code>limit?</code> (default 20, at most 50)</td><td><code>MailSearchResult</code>: summaries newest first, <code>truncated</code> when more matched</td></tr><tr><td><code>mail_get</code></td><td><code>id</code>, <code>offset?</code></td><td><code>MailMessage</code>: headers (subject cut at 1 000 characters, address lists at 2 000), the text body (HTML stripped) in pages of 50 000 characters, up to 10 invite summaries, the attachment list</td></tr><tr><td><code>mail_attachment</code></td><td><code>id</code>, <code>index</code>, <code>offset?</code></td><td><code>MailAttachmentText</code>: the text of a PDF (the first 50 pages), docx, xlsx, pptx or text file in pages of 20 000 characters; <code>(text extraction failed)</code> for a broken file</td></tr><tr><td><code>mail_thread</code></td><td><code>id</code>, <code>limit?</code></td><td><code>MailSearchResult</code>: the other mails of the thread, across the folders and Sent</td></tr></tbody></table><ul><li><strong>Read-only.</strong> Folders are opened with <code>EXAMINE</code>, never <code>SELECT</code>; every body fetch is <code>BODY.PEEK</code>, so <code>\\Seen</code> stays as it is; IDLE is off. The client has no method that writes.</li><li><strong>Mail ids</strong> are <code>&lt;account&gt;:&lt;folder&gt;:&lt;uidValidity&gt;:&lt;uid&gt;</code> (the folder base64url-encoded), issued by the tools. An unknown account, a folder outside the account&#39;s folders (refused before it is opened), a changed <code>UIDVALIDITY</code> or a missing uid is a <code>ValidationError</code> (<code>mail id is stale, search again</code>).</li><li><strong>Folders.</strong> Without <code>folder</code>, a search covers <code>account.folders</code>, else on Gmail All Mail, else every folder but trash and spam. On Gmail <code>query</code> is Gmail search syntax and threads follow <code>X-GM-THRID</code>; elsewhere <code>query</code> is IMAP full text and threads follow <code>Message-ID</code>, <code>In-Reply-To</code> and the last 10 <code>References</code>.</li><li><strong>Caps.</strong> A mail above 25 MiB is not fetched (<code>truncated: true</code>, headers and attachments only). HTML is cut at 1 000 000 characters before stripping; OOXML parts above 10 MiB are skipped. Attachment bytes are never returned or stored.</li><li><strong>Errors.</strong> A malformed input is a <code>ValidationError</code>; a failed request (login, connection, a timeout after <code>timeoutMs</code> on the clock) a <code>ChamviError</code> with code <code>mail_request</code> and the message <code>&lt;tool&gt;: &lt;account&gt;: &lt;reason&gt;</code>, never the server&#39;s text or a credential. Both are tool errors the model reads.</li></ul><p>Every tool declares <code>trust: { taint: true }</code>: a result taints the run.</p><h2 id="toolmailmodule" tabindex="-1">toolMailModule <a class="header-anchor" href="#toolmailmodule" aria-label="Permalink to &quot;toolMailModule&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">// @chamvi/tool-mail/module</span></span>
<span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> toolMailModule(options?: ToolMailModuleOptions): ToolMailModule; </span><span style="color:#7F95A6;">// &#39;chamvi:tool-mail&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> ToolMailModuleOptions = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    env?: Record&lt;string, string | undefined&gt;; </span><span style="color:#7F95A6;">// where CHAMVI_MAIL_* is read, default process.env</span></span>
<span class="line"><span style="color:#DCE9F2;">    accounts?: MailAccount[];                  </span><span style="color:#7F95A6;">// given, CHAMVI_MAIL_ACCOUNTS is not read</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> TOOL_MAIL_MODULE_NAME: </span><span style="color:#E7C58C;">&#39;chamvi:tool-mail&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> MAIL_ACCOUNTS_VARIABLE: </span><span style="color:#E7C58C;">&#39;CHAMVI_MAIL_ACCOUNTS&#39;</span><span style="color:#DCE9F2;">;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Variable</th><th></th></tr></thead><tbody><tr><td><code>CHAMVI_MAIL_ACCOUNTS</code></td><td>A JSON array of <code>{ &quot;id&quot;?, &quot;address&quot;, &quot;host&quot;, &quot;port&quot;?, &quot;security&quot;?, &quot;folders&quot;?, &quot;gmail&quot;? }</code>; <code>id</code> defaults to the address with <code>@</code> and <code>.</code> as <code>-</code></td></tr><tr><td><code>CHAMVI_MAIL_&lt;ID&gt;_USER</code></td><td>The account&#39;s user, default the address; <code>&lt;ID&gt;</code> is the id upper-cased, <code>-</code> as <code>_</code></td></tr><tr><td><code>CHAMVI_MAIL_&lt;ID&gt;_PASSWORD</code></td><td>Required</td></tr></tbody></table><p>For an account listed in <code>CHAMVI_MAIL_ACCOUNTS</code> each credential can come from a file instead: <code>CHAMVI_MAIL_&lt;ID&gt;_PASSWORD_FILE</code> (one trailing newline trimmed; setting both forms is an error). The variables are read and checked when the factory is called; an error names the variable and index, never a value. Accounts stored in the connection store (added on the dashboard through <a href="/guide/ui#connection-pages"><code>toolMailUiModule()</code></a>) are added at start (<code>accounts</code> pins the set). For an account listed in <code>CHAMVI_MAIL_ACCOUNTS</code> a variable wins per field over its stored value, and a password in neither env nor store fails at startup naming the variable. An account that exists only in the store takes every value from the store: a <code>CHAMVI_MAIL_&lt;ID&gt;_*</code> variable named after it is ignored with a warning naming the variable, and a missing password lists it <code>incomplete</code>. Without any account the context stays provided and tools return a <code>connection_not_configured</code> tool error. In start and job mode and a check it builds one client on the app&#39;s clock, provides it on the engine (<code>injectMailContext(ctx)</code>) and logs out once the engine drained; migrate mode does nothing.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> MailAccount = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    id: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    host: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    port?: number;                                </span><span style="color:#7F95A6;">// default 993 with tls, else 143</span></span>
<span class="line"><span style="color:#DCE9F2;">    security?: </span><span style="color:#E7C58C;">&#39;tls&#39;</span><span style="color:#DCE9F2;"> | </span><span style="color:#E7C58C;">&#39;starttls&#39;</span><span style="color:#DCE9F2;"> | </span><span style="color:#E7C58C;">&#39;plain&#39;</span><span style="color:#DCE9F2;">;      </span><span style="color:#7F95A6;">// default tls</span></span>
<span class="line"><span style="color:#DCE9F2;">    user: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    password: string;                             </span><span style="color:#7F95A6;">// Gmail: an app password</span></span>
<span class="line"><span style="color:#DCE9F2;">    address?: string;                             </span><span style="color:#7F95A6;">// default user</span></span>
<span class="line"><span style="color:#DCE9F2;">    folders?: string[];                           </span><span style="color:#7F95A6;">// the folders searched and read</span></span>
<span class="line"><span style="color:#DCE9F2;">    gmail?: boolean;                              </span><span style="color:#7F95A6;">// default host === &#39;imap.gmail.com&#39;</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> MailToolsOptions = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    accounts?: MailAccount[];</span></span>
<span class="line"><span style="color:#DCE9F2;">    client?: IMailClient;   </span><span style="color:#7F95A6;">// wins over accounts</span></span>
<span class="line"><span style="color:#DCE9F2;">    clock?: IClock;</span></span>
<span class="line"><span style="color:#DCE9F2;">    timeoutMs?: number;     </span><span style="color:#7F95A6;">// default 30 s per call, connecting included</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> MailClientOptions = { clock?: IClock; timeoutMs?: number };</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">interface</span><span style="color:#DCE9F2;"> IMailClient {</span></span>
<span class="line"><span style="color:#DCE9F2;">    accounts(signal?: AbortSignal): Promise&lt;MailAccountView[]&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    search(input: MailSearchInput, signal?: AbortSignal): Promise&lt;MailSearchResult&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    get(id: string, offset?: number, signal?: AbortSignal): Promise&lt;MailMessage&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    attachment(id: string, index: number, offset?: number, signal?: AbortSignal): Promise&lt;MailAttachmentText&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    thread(id: string, limit?: number, signal?: AbortSignal): Promise&lt;MailSearchResult&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    close(): Promise&lt;void&gt;; </span><span style="color:#7F95A6;">// logs out of every account</span></span>
<span class="line"><span style="color:#DCE9F2;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> provideMailContext(provider: IContextProvider, client: IMailClient): void;</span></span>
<span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> injectMailContext(ctx: ToolContext): IMailClient; </span><span style="color:#7F95A6;">// ContextNotProvidedError without one</span></span>
<span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> encodeMailId(parts: MailIdParts): string;</span></span>
<span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> parseMailId(id: unknown): MailIdParts;            </span><span style="color:#7F95A6;">// ValidationError for anything else</span></span></code></pre></div><p><code>MailSummary</code>, <code>MailMessage</code>, <code>MailAttachmentInfo</code>, <code>MailAttachmentText</code>, <code>MailAccountView</code>, <code>MailFolderView</code>, <code>MailSearchInput</code>, <code>MailSearchResult</code> and <code>MailIdParts</code> are exported too; the <a href="https://github.com/chamvi/chamvi/tree/master/packages/tool-mail#the-tools" target="_blank" rel="noreferrer">package README</a> lists their fields.</p>`,17)])])}const u=a(t,[["render",l]]);export{y as __pageData,u as default};
